module field_of_wonders (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] n,\n    input wire [63:0] pattern,\n    input wire [3:0] m,\n    input wire [63:0] word0,\n    input wire [63:0] word1,\n    input wire [63:0] word2,\n    input wire [63:0] word3,\n    input wire [63:0] word4,\n    input wire [63:0] word5,\n    input wire [63:0] word6,\n    input wire [63:0] word7,\n    output reg [4:0] result,\n    output reg done\n);\n\n    // State declarations\n    localparam [1:0] IDLE         = 2'd0;\n    localparam [1:0] CHECK_WORDS  = 2'd1;\n    localparam [1:0] COUNT_LETTERS = 2'd2;\n    localparam [1:0] DONE_STATE   = 2'd3;\n    \n    reg [1:0] state, next_state;\n    reg [2:0] word_idx;\n    reg [4:0] letter_idx;\n    reg [25:0] revealed_mask;\n    reg [7:0] valid_words;\n    reg [25:0] hidden_masks [0:7];\n    reg [3:0] total_valid;\n    reg [4:0] result_reg;\n    \n    // Current word selection\n    wire [63:0] current_word;\n    assign current_word = (word_idx == 3'd0) ? word0 :\n                         (word_idx == 3'd1) ? word1 :\n                         (word_idx == 3'd2) ? word2 :\n                         (word_idx == 3'd3) ? word3 :\n                         (word_idx == 3'd4) ? word4 :\n                         (word_idx == 3'd5) ? word5 :\n                         (word_idx == 3'd6) ? word6 : word7;\n    \n    // Word validation logic\n    reg valid_flag;\n    reg [25:0] current_hidden_mask;\n    integer j;\n    always @(*) begin\n        valid_flag = 1'b1;\n        current_hidden_mask = 26'd0;\n        if (state == CHECK_WORDS && word_idx < m) begin\n            for (j = 0; j < 8; j = j + 1) begin\n                if (j < n) begin\n                    reg [7:0] pattern_char = pattern[j*8 +:8];\n                    reg [7:0] word_char = current_word[j*8 +:8];\n                    \n                    if (pattern_char != 8'h2A) begin\n                        if (pattern_char != word_char)\n                            valid_flag = 1'b0;\n                    end else begin\n                        if (word_char < 8'h61 || word_char > 8'h7A)\n                            valid_flag = 1'b0;\n                        else if (revealed_mask[word_char - 8'h61])\n                            valid_flag = 1'b0;\n                        else\n                            current_hidden_mask[word_char - 8'h61] = 1'b1;\n                    end\n                end\n            end\n        end\n    end\n    \n    // State transition and control\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            word_idx <= 3'd0;\n            letter_idx <= 5'd0;\n            revealed_mask <= 26'd0;\n            valid_words <= 8'd0;\n            total_valid <= 4'd0;\n            result_reg <= 5'd0;\n            result <= 5'd0;\n            done <= 1'b0;\n            for (integer i = 0; i < 8; i = i + 1)\n                hidden_masks[i] <= 26'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= CHECK_WORDS;\n                        word_idx <= 3'd0;\n                        total_valid <= 4'd0;\n                        valid_words <= 8'd0;\n                        result_reg <= 5'd0;\n                        // Build revealed mask\n                        revealed_mask <= 26'd0;\n                        for (integer k = 0; k < 8; k = k + 1)\n                            if (k < n) begin\n                                reg [7:0] p_char = pattern[k*8 +:8];\n                                if (p_char != 8'h2A && p_char >= 8'h61 && p_char <= 8'h7A)\n                                    revealed_mask[p_char - 8'h61] <= 1'b1;\n                            end\n                    end\n                end\n                \n                CHECK_WORDS: begin\n                    if (word_idx < m) begin\n                        if (valid_flag) begin\n                            valid_words[word_idx] <= 1'b1;\n                            hidden_masks[word_idx] <= current_hidden_mask;\n                            total_valid <= total_valid + 4'd1;\n                        end\n                        word_idx <= word_idx + 3'd1;\n                    end else begin\n                        state <= COUNT_LETTERS;\n                        letter_idx <= 5'd0;\n                    end\n                end\n                \n                COUNT_LETTERS: begin\n                    if (letter_idx < 5'd26) begin\n                        if (!revealed_mask[letter_idx]) begin\n                            reg [4:0] count = 5'd0;\n                            for (integer w = 0; w < 8; w = w + 1) begin\n                                if (w < m && valid_words[w] && hidden_masks[w][letter_idx])\n                                    count = count + 5'd1;\n                            end\n                            if (count == total_valid && total_valid != 4'd0)\n                                result_reg <= result_reg + 5'd1;\n                        end\n                        letter_idx <= letter_idx + 5'd1;\n                    end else begin\n                        result <= result_reg;\n                        state <= DONE_STATE;\n                        done <= 1'b1;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    // Maintain done signal until reset\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule